//! Port of `packages/quicktype-core/src/Annotation.ts`.
//!
//! Annotations mark spans of generated code. They never change the
//! generated bytes; the CLI prints issue annotations to stderr unless
//! `--quiet` is given.

/// `AnnotationData` and its only subclass, `IssueAnnotationData`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum AnnotationData {
    /// `IssueAnnotationData(message)`: a problem with the input, e.g. a type
    /// that could not be inferred.
    Issue {
        /// The message shown to the user.
        message: String,
    },
}

impl AnnotationData {
    /// `new IssueAnnotationData(message)`.
    pub fn issue(message: impl Into<String>) -> Self {
        AnnotationData::Issue {
            message: message.into(),
        }
    }

    /// The issue message.
    pub fn message(&self) -> &str {
        match self {
            AnnotationData::Issue { message } => message,
        }
    }
}

/// The message of [`any_type_issue_annotation`].
pub const ANY_TYPE_ISSUE_MESSAGE: &str =
    "quicktype cannot infer this type because there is no data about it in the input.";

/// The message of [`null_type_issue_annotation`].
pub const NULL_TYPE_ISSUE_MESSAGE: &str = "The only value for this in the input is null, which means you probably need a more complete input sample.";

/// `anyTypeIssueAnnotation`.
pub fn any_type_issue_annotation() -> AnnotationData {
    AnnotationData::issue(ANY_TYPE_ISSUE_MESSAGE)
}

/// `nullTypeIssueAnnotation`.
pub fn null_type_issue_annotation() -> AnnotationData {
    AnnotationData::issue(NULL_TYPE_ISSUE_MESSAGE)
}
